Class Animal
  Define nombre As String;

  Method Constructor(n As String)
    This.nombre <- n;
  EndMethod

  Method Sonido() As String
    Return "...";
  EndMethod

  Method Presentarse() As String
    Return This.nombre + " dice " + This.Sonido();
  EndMethod
EndClass

Class Perro Inherits From Animal
  Method Constructor(n As String)
    Super.constructor(n);
  EndMethod

  Method Sonido() As String
    Return "guau";
  EndMethod
EndClass

Algorithm Granja
  Define a As Animal <- New Perro("Toby");
  Write a.Presentarse();
  Define b As Animal <- New Animal("Pez");
  Write b.Presentarse();
EndAlgorithm
